#!/usr/bin/env python3
"""Apply explicit, source-backed rule decisions from the deeper investigation.

Rules are named explicitly. No keyword-based pass assignment is performed here.
All dispositions are recommendations for pinned source/configuration, not a claim
that official runtime tests were executed or that an assessor accepted a result.
"""
import json
from pathlib import Path
import build_review as b
ROOT=Path(__file__).resolve().parents[1]
CORE='c15677633cffa17e99656a7d7ccd1f98d7cb6e4d'
ID='74480722e1cc8405b5e9b65ac7d7086ab7f4056d'
SRC=Path('/private/tmp/horizon-stig-review-20261109')
FACTS={}
DECISIONS={}
RULES={r['vuln_id']:r for p in (ROOT/'mpn/benchmarks').glob('*/rules.json') for r in json.loads(p.read_text())}

def fact(key, repo, commit, path, text):
 local={'uds-core':SRC/'uds-core-v1.14.0','uds-identity-config':SRC/'uds-identity-config-v0.32.0','horizon':SRC/'horizon','horizon-uds-bundle':SRC/'horizon-uds-bundle'}[repo]/path
 assert local.exists(),local
 org='defenseunicorns' if repo.startswith('uds-') else 'gallatinai'
 url=f'https://github.com/{org}/{repo}/blob/{commit}/{path}'
 b.E[key]=(key,text,url)
 FACTS[key]={'repo':repo,'commit':commit,'path':path,'observation':text,'url':url}

def decide(ids,status,why,ev,next_step='',task='',category='source/configuration',owner='Gallatin SRE; MPN/UDS operator for inherited controls'):
 for raw in ids.split():
  v='V-'+raw.removeprefix('V-');assert v in RULES,v
  assert all(e in b.E for e in ev.split()),ev
  DECISIONS[v]=dict(status=status,justification=why,evidence_ids=ev.split(),next_step=next_step or 'Retain this source mapping with the selected release; verify only deployment overrides, exemptions and applicability before final checklist sign-off.',task=task,category=category,owner=owner,evidence_state='source-inferred',investigation='Explicit official-rule decision from pinned Core/Horizon source and configuration. No live MPN test claimed.')

